export type AuthoredMcq = readonly [
  subtopicId: string | null,
  text: string,
  options: readonly [string, string, string, string],
  correctIndex: 0 | 1 | 2 | 3,
  explanation: string,
  linkedConcept: string,
];

export type AuthoredEssay = readonly [
  subtopicId: string | null,
  text: string,
  markingGuide: string,
  linkedConcept: string,
];

export type AuthoredTopicQuestions = {
  topicId: string;
  mcqs: readonly AuthoredMcq[];
  essays: readonly AuthoredEssay[];
};

const topicQuestions = (
  topicId: string,
  mcqs: readonly AuthoredMcq[],
  essays: readonly AuthoredEssay[],
): AuthoredTopicQuestions => ({ topicId, mcqs, essays });

